use validator::{Validate, ValidationError};

fn port_ok(p: &i32) -> Result<(), ValidationError> {
    if (1..=65_535).contains(p) { Ok(()) } else { Err(ValidationError::new("port")) }
}

#[derive(Validate)]
struct Config {
    #[validate(length(min = 1))] host: String,
    #[validate(custom(function = "port_ok"))] port: i32,
}
let errors = config.validate().unwrap_err();   // one entry per failing field

type Rule<T, E> = Box<dyn Fn(&T) -> Result<(), E>>;

fn all<T: Copy, E>(rules: &[Rule<T, E>], v: T) -> Result<(), Vec<E>> {
    let errs: Vec<E> = rules.iter().filter_map(|r| r(&v).err()).collect();   // accumulate
    if errs.is_empty() { Ok(()) } else { Err(errs) }
}

fn valid(plane: Plane) -> bool {
    match plane { Plane::Num(n) => n > 0, Plane::Name(s) => !s.is_empty() }   // choose
}
